<?php
$current = $record ?? [];
$currentData = old('datos', $current['datos'] ?? []);
if (!is_array($currentData)) $currentData = [];
$value = static fn(string $key, mixed $default = '') => old($key, $current[$key] ?? $default);
$selectedRequirement = old('requerimiento_id', $current['requerimiento_id'] ?? ($selectedRequirement ?? 0));
?>
<form method="post" action="<?= e(url($formAction)) ?>" class="mt-6 space-y-6">
    <?= csrf_field() ?><input type="hidden" name="tipo" value="<?= e($type) ?>">
    <section class="ios-card p-5 sm:p-7"><div class="section-heading"><span class="section-icon"><?= icon($definition['icon'], 'h-5 w-5') ?></span><div><h2>Información general</h2><p>Identifica el registro, su responsable y su relación con el seguimiento IVC.</p></div></div><div class="mt-6 grid gap-5 sm:grid-cols-2">
        <div class="sm:col-span-2"><label class="label" for="sanitary-title">Título del registro *</label><input id="sanitary-title" name="titulo" class="input" maxlength="220" required value="<?= e($value('titulo')) ?>" placeholder="Ej. Lavado y desinfección del tanque · sede principal"><?= field_error('titulo') ?></div>
        <div><label class="label" for="sanitary-date">Fecha del registro o actividad *</label><input id="sanitary-date" name="fecha_registro" type="date" class="input" required value="<?= e($value('fecha_registro', date('Y-m-d'))) ?>"><?= field_error('fecha_registro') ?><p class="mt-1.5 text-[10px] text-slate-400">Usa la fecha real; no antedates ejecuciones.</p></div>
        <div><label class="label" for="sanitary-owner">Responsable *</label><input id="sanitary-owner" name="responsable" class="input" maxlength="250" required value="<?= e($value('responsable')) ?>"><?= field_error('responsable') ?></div>
        <div><label class="label" for="sanitary-state">Estado *</label><select id="sanitary-state" name="estado" class="input" required><?php foreach (App\Models\SanitarioRegistro::ESTADOS as $state): ?><option value="<?= e($state) ?>"<?= selected($value('estado', 'Pendiente'), $state) ?>><?= e($state) ?></option><?php endforeach; ?></select><?= field_error('estado') ?></div>
        <div><label class="label" for="sanitary-requirement">Requerimiento IVC relacionado</label><select id="sanitary-requirement" name="requerimiento_id" class="input"><option value="0">Sin vínculo específico</option><?php foreach ($requirements as $requirement): ?><option value="<?= (int) $requirement['id'] ?>"<?= selected($selectedRequirement, $requirement['id']) ?>><?= e($requirement['codigo'] . ' · Acta ' . $requirement['numero_acta'] . ' · ' . excerpt($requirement['hallazgo'], 65)) ?></option><?php endforeach; ?></select><?= field_error('requerimiento_id') ?></div>
    </div></section>
    <section class="ios-card p-5 sm:p-7"><div class="section-heading"><span class="section-icon"><?= icon('grid', 'h-5 w-5') ?></span><div><h2>Campos de <?= e($definition['label']) ?></h2><p><?= e($definition['description']) ?></p></div></div><?= field_error('datos') ?><div class="mt-6 grid gap-5 sm:grid-cols-2"><?php foreach ($definition['fields'] as $field): ?><?php $key = $field['key']; $fieldId = 'sanitary-' . $key; $fieldValue = $currentData[$key] ?? ''; $wide = $field['type'] === 'textarea'; ?><div class="<?= $wide ? 'sm:col-span-2' : '' ?>"><label class="label" for="<?= e($fieldId) ?>"><?= e($field['label']) ?><?= $field['required'] ? ' *' : '' ?></label><?php if ($field['type'] === 'textarea'): ?><textarea id="<?= e($fieldId) ?>" name="datos[<?= e($key) ?>]" class="input min-h-24" maxlength="5000"<?= $field['required'] ? ' required' : '' ?>><?= e($fieldValue) ?></textarea><?php elseif ($field['type'] === 'select'): ?><select id="<?= e($fieldId) ?>" name="datos[<?= e($key) ?>]" class="input"<?= $field['required'] ? ' required' : '' ?>><option value="">Sin especificar</option><?php foreach ($field['options'] as $option): ?><option value="<?= e($option) ?>"<?= selected($fieldValue, $option) ?>><?= e($option) ?></option><?php endforeach; ?></select><?php else: ?><input id="<?= e($fieldId) ?>" name="datos[<?= e($key) ?>]" type="<?= e($field['type']) ?>" class="input" maxlength="500"<?= $field['type'] === 'number' ? ' min="0" step="any"' : '' ?><?= $field['required'] ? ' required' : '' ?> value="<?= e($fieldValue) ?>"><?php endif; ?><?= field_error('datos_' . $key) ?></div><?php endforeach; ?></div></section>
    <section class="ios-card p-5 sm:p-7"><label class="label" for="sanitary-notes">Observaciones, verificación o justificación</label><textarea id="sanitary-notes" name="observaciones" class="input min-h-28" maxlength="5000" placeholder="Resultado, alcance, limitaciones, persona que verificó y soportes relacionados. Obligatorio para Verificado o No aplica."><?= e($value('observaciones')) ?></textarea><?= field_error('observaciones') ?><div class="mt-4 rounded-2xl bg-amber-50 p-4 text-[11px] leading-5 text-amber-900">El estado Verificado documenta una revisión interna. No cambia automáticamente el requerimiento IVC ni representa aceptación de una autoridad.</div><div class="mt-6 flex flex-wrap justify-end gap-3"><a href="<?= e(url($cancelUrl)) ?>" class="btn-secondary">Cancelar</a><button type="submit" class="btn-primary"><?= icon('check', 'h-4 w-4') ?> Guardar registro</button></div></section>
</form>
